/* ============================================
   SITE HEADER
   The site's top bar: brand, section pills with
   mega menus, actions, and a drawer once folded
   ============================================ */

/* Base */
.ds-site-header {
  /* The bar's height. An override hook: the blur's reach and a page's own
     anchor offsets read it. */
  --ds-site-header-height: calc(var(--control-height-default) + var(--padding-1000));
  /* How far the blur dissolves below the bar. */
  --ds-site-header-blur-reach: var(--gap-1500);
  position: relative;
  /* Lifts the open panel over the page's flow when the header is not sticky. */
  z-index: 1;
  width: 100%;
}

/* Sticky: rides up with whatever sits above it, then holds at the top. */
.ds-site-header--sticky {
  position: sticky;
  top: 0;
  z-index: var(--layer-sticky);
}

/* The blur stack, viewport-fixed (a sticky box is not a containing block
   for it) so it spans the full width whatever the host's gutters. It sits
   inside the header's stacking context, behind the bar's controls. Never a
   filter on the header itself: that would make the header a backdrop root
   and the mega menu's own glass would sample only the header's subtree. */
.ds-site-header__blur.ds-progressive-blur {
  position: fixed;
  inset: 0 0 auto;
  height: calc(var(--ds-site-header-height) + var(--ds-site-header-blur-reach));
  z-index: -1;
}

/* The bar: brand, pills, then the end cluster pushed to the far side. */
.ds-site-header__bar {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--gap-400);
  height: var(--ds-site-header-height);
  box-sizing: border-box;
  /* The folded bar keeps its pills out of flow at full width so they stay
     measurable; clipping the inline axis keeps them from widening the page
     into a sideways scroll. The margin leaves room for a focus ring at the
     bar's edge, and the block axis stays open for the menu panel. */
  overflow-x: clip;
  overflow-clip-margin: var(--gap-200);
}

.ds-site-header__brand {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

/* The pills sit beside the brand rather than centred on the page:
   --gap-1000 from the brand (the bar's own gap plus this margin), and the
   first pill's inline padding sets the rest of the visual gap. */
.ds-site-header__nav {
  display: flex;
  align-items: center;
  gap: var(--gap-100);
  margin-inline-start: calc(var(--gap-1000) - var(--gap-400));
  flex-shrink: 0;
}

.ds-site-header__end {
  display: flex;
  align-items: center;
  gap: var(--gap-400);
  margin-inline-start: auto;
  flex-shrink: 0;
}

.ds-site-header__actions,
.ds-site-header__wide-actions {
  display: flex;
  align-items: center;
  gap: var(--gap-400);
  flex-shrink: 0;
}

.ds-site-header__section {
  position: relative;
}

/* Pills: a pill-radius link at the compact control height, so a caret's
   icon box never makes one pill taller than its neighbours. */
.ds-site-header__pill {
  display: inline-flex;
  align-items: center;
  gap: var(--gap-050);
  height: var(--control-height-compact);
  box-sizing: border-box;
  padding-inline: var(--padding-400);
  border-radius: var(--radius-pill);
  background-color: transparent;
  color: var(--color-text-primary);
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
  line-height: 1;
  white-space: nowrap;
  text-decoration: none;
  transition:
    background-color var(--motion-duration-fast) var(--motion-ease-standard),
    color var(--motion-duration-fast) var(--motion-ease-standard);
}

/* Hover is the tertiary family's wash, as on a tertiary Button, a NavList
   row and the MegaMenu's rows: a container fill can match the page floor
   in a light theme and vanish. */
.ds-site-header__pill:hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-site-header__pill:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

/* An open menu holds the hover fill and nothing more: opening a menu is
   not a selection. Declared before --current so the current section keeps
   its colour while its menu is open. */
.ds-site-header__pill--open {
  background-color: var(--color-action-passive-bg-hover);
}

/* The current section is the selected item of an exclusive set, so it
   takes the action selection pair, SegmentedControl's active segment; a
   neutral fill would read as the hover state over the glassy blur. */
.ds-site-header__pill--current {
  background-color: var(--color-action-primary-bg);
  color: var(--color-action-primary-text);
}

.ds-site-header__pill--current:hover {
  background-color: var(--color-action-primary-bg-hover);
}

.ds-site-header__caret {
  --icon-size: var(--icon-size-500);
  line-height: 1;
  color: var(--color-text-secondary);
  transition: rotate var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-site-header__pill--current .ds-site-header__caret {
  color: inherit;
}

.ds-site-header__pill--open .ds-site-header__caret {
  rotate: 180deg;
}

/* The menu button only exists once the bar folds. */
.ds-site-header__menu-button {
  display: none;
}

/* While the drawer is open its close button stands in this exact spot, on
   the top layer; the button underneath would only show through the scrim. */
.ds-site-header__menu-button--hidden {
  visibility: hidden;
}

/* The mega menu hangs under the bar across its full width. It is not
   anchored to a control (useAnchoredPosition's job): it belongs to the bar
   and spans it, so it rides the bar's own box.
   The wrapper keeps the height of the last section shown after the menu
   closes, so it never takes a press itself: a transparent box that size
   would sit over the page and swallow its clicks. Only the menu does, and a
   closed menu is hidden, which takes it out of hit testing too. */
.ds-site-header__panel {
  position: absolute;
  inset-block-start: calc(100% + var(--gap-200));
  inset-inline: 0;
  pointer-events: none;
}

.ds-site-header__panel > .ds-mega-menu {
  pointer-events: auto;
}

/* Folded: the pills and the wide actions leave the row but stay measurable
   (hidden, out of flow, inert), and the menu button takes their place. */
.ds-site-header--folded .ds-site-header__nav,
.ds-site-header--folded .ds-site-header__wide-actions {
  position: absolute;
  visibility: hidden;
  pointer-events: none;
}

.ds-site-header--folded .ds-site-header__menu-button {
  display: inline-flex;
}

.ds-site-header--folded .ds-site-header__panel {
  display: none;
}

/* Before the bar has measured itself (the first frame, which a
   server-rendered page shows before its script runs), it folds by CSS below
   the `initialFold` step, so a phone never sees the pills spill past the
   actions. The first measurement replaces this in the same commit as
   hydration. */
@media (max-width: 959px) {
  .ds-site-header--prefold-tablet .ds-site-header__nav,
  .ds-site-header--prefold-tablet .ds-site-header__wide-actions {
    position: absolute;
    visibility: hidden;
    pointer-events: none;
  }

  .ds-site-header--prefold-tablet .ds-site-header__menu-button {
    display: inline-flex;
  }
}

@media (max-width: 1279px) {
  .ds-site-header--prefold-mid .ds-site-header__nav,
  .ds-site-header--prefold-mid .ds-site-header__wide-actions {
    position: absolute;
    visibility: hidden;
    pointer-events: none;
  }

  .ds-site-header--prefold-mid .ds-site-header__menu-button {
    display: inline-flex;
  }
}

/* The drawer: its brand row lands on the bar's own brand. SiteHeader
   measures the bar as the drawer opens (its top, which is 0 once stuck and
   the host's gutter at rest, and its inline start) and the panel takes
   those as its padding, with the header row the bar's height, so the
   panel slides in under a brand that does not move. */
.ds-site-header__drawer .ds-drawer__panel {
  width: min(320px, 80vw);
  padding-block-start: var(--ds-site-header-drawer-top, var(--padding-500));
  padding-inline-start: var(--ds-site-header-drawer-start, var(--padding-500));
  /* The floating glass the command palette wears, so the page reaches
     through the menu frosted rather than behind an opaque sheet. The
     panel lets its close button out (below); its body still scrolls. */
  background-color: var(--color-bg-glass);
  backdrop-filter: blur(24px);
  overflow: visible;
}

/* The drawer's close button swaps with the menu button: it sits on the
   scrim exactly where the menu button was (measured as the drawer opens),
   and fades in once the panel has slid home, so the X never travels with
   it. It stays the drawer's own button, inside its focus trap. */
.ds-site-header__drawer .ds-drawer__close {
  position: absolute;
  inset-block-start: var(--ds-site-header-close-top, var(--padding-500));
  inset-inline-start: var(--ds-site-header-close-start, auto);
  width: var(--control-height-default);
  height: var(--control-height-default);
  /* ds-allow(color): on-scrim furniture, as Lightbox's: the scrim is dark in both themes, so the glyph is white in both. */
  color: #ffffff;
  opacity: 0;
  transition: opacity var(--motion-duration-fast) var(--motion-ease-standard);
}

/* The glyph at the menu button's own size, so the swap reads as one icon
   turning into another. */
.ds-site-header__drawer .ds-drawer__close .material-symbols-rounded {
  --icon-size: var(--icon-size-600);
}

.ds-site-header__drawer .ds-drawer__panel[data-state="open"] .ds-drawer__close {
  opacity: 1;
  transition-delay: var(--motion-duration-slow);
}

.ds-site-header__drawer .ds-drawer__close:hover {
  /* ds-allow(color): the hover wash on the always-dark scrim, as Lightbox's controls. */
  background-color: rgba(255, 255, 255, 0.15);
}

/* The footer row starts under the brand, not at the panel's far edge. */
.ds-site-header__drawer .ds-drawer__footer {
  justify-content: flex-start;
}

.ds-site-header__drawer .ds-drawer__header {
  align-items: center;
  height: var(--ds-site-header-height, auto);
}

.ds-site-header__drawer-brand {
  display: flex;
  align-items: center;
}

.ds-site-header__drawer .ds-nav-list {
  width: 100%;
}

'use client';

import React, { useCallback, useEffect, useId, useLayoutEffect, useRef, useState } from 'react';
import { useLinkComponent, type LinkComponent } from '../../behaviors/LinkProvider';
import { useLayer } from '../../behaviors/useLayer';
import { isRtl } from '../../behaviors/direction';
import { MOTION_HOVER_HIDE_DELAY_MS } from '../../tokens/motion';
import { CircularButton } from '../CircularButton/CircularButton';
import { Drawer } from '../Drawer/Drawer';
import { MegaMenu, type MegaMenuItem, type MegaMenuShowcase } from '../MegaMenu/MegaMenu';
import { NavList, type NavListItem } from '../NavList/NavList';
import { ProgressiveBlur } from '../ProgressiveBlur/ProgressiveBlur';
import './SiteHeader.css';
import '../../fonts/material-symbols.css';

/** One top-level section of the site: a pill in the bar, a row in the drawer. */
export interface SiteHeaderSection {
  /** A stable key for the section. */
  id: string;
  /** The pill's text. */
  label: string;
  /** The section's landing page: where a click on the pill goes. */
  href: string;
  /**
   * A mega menu for the section. Hovering or focusing the pill opens it; its
   * items are also the section's sub-list in the drawer.
   */
  mega?: {
    /** The panel's link rows. */
    items: MegaMenuItem[];
    /** A featured card beside the rows. */
    showcase?: MegaMenuShowcase;
  };
  /**
   * The section's sub-list in the drawer, when it should differ from its
   * menu's items: a page that needs a wide screen, say, left out of the
   * drawer that only narrow screens see. Defaults to the menu's items.
   */
  drawerItems?: { href: string; label: string }[];
  /**
   * Marks the section as the one being viewed. Left unset, the header works
   * it out from `currentHref`: the section's own page, a page under it, or
   * any page its menu lists.
   */
  current?: boolean;
}

/** Props owned by SiteHeader itself — everything else falls through to the `<header>`. */
type SiteHeaderOwnProps = {
  /**
   * The brand at the bar's start, usually a logo linking home. Rendered as
   * given, so it carries its own link.
   */
  brand?: React.ReactNode;
  /** The site's top-level sections, in order. */
  sections: SiteHeaderSection[];
  /** The path of the page being viewed, used to mark the current section, row and drawer item. */
  currentHref?: string;
  /** Controls at the bar's end that stay at every width, such as a search button. */
  actions?: React.ReactNode;
  /**
   * Controls at the bar's end that show only while the pills fit, such as a
   * theme toggle. Once the bar folds to its menu button they leave it; put
   * their drawer twin in `drawerFooter`.
   */
  wideActions?: React.ReactNode;
  /** Content for the drawer's footer, such as the controls `wideActions` holds in the bar. */
  drawerFooter?: React.ReactNode;
  /** Whether the folded bar's drawer is open, for a host that owns that state. Pair with `onDrawerOpenChange`. */
  drawerOpen?: boolean;
  /** Whether the drawer starts open, when the header owns its state. */
  defaultDrawerOpen?: boolean;
  /** Called when the drawer opens or closes, controlled or not. */
  onDrawerOpenChange?: (open: boolean) => void;
  /**
   * Where the bar folds before it has measured itself: on the first frame,
   * which a server-rendered page shows before its script runs. Below this
   * breakpoint (`tablet` or the wider `mid`) the bar starts folded by CSS
   * alone, so a phone never sees the pills overflow; the measurement takes
   * over once the script runs. Pick the step nearest where the pills stop
   * fitting, or `never` for a bar that fits at every width.
   */
  initialFold?: 'tablet' | 'mid' | 'never';
  /**
   * Whether the header sticks to the top of the viewport over a progressive
   * blur. Off, it scrolls away with the page and draws no blur.
   */
  sticky?: boolean;
  /**
   * How far, in pixels, the page scrolls before the page-surface tint fades
   * in over the sticky header's blur.
   */
  tintAfter?: number;
  /**
   * The component every link renders through, so a router's link (Next.js
   * `Link`) navigates without a reload. Falls back to the nearest
   * `LinkProvider`, then `<a>`.
   */
  linkComponent?: LinkComponent;
  /** The accessible name of the section links' `<nav>` landmark. */
  navLabel?: string;
  /** The accessible name of the menu button that opens the drawer. */
  drawerOpenLabel?: string;
  /**
   * The drawer's title, naming the dialog. Shown at its top when there is no
   * `brand`; with one, the brand takes its place and the title is read only
   * by assistive tech.
   */
  drawerTitle?: string;
  /** The accessible name of the drawer's close button. */
  drawerCloseLabel?: string;
  /** Additional CSS classes on the `<header>`. */
  className?: string;
};

export interface SiteHeaderProps
  extends SiteHeaderOwnProps,
    Omit<React.ComponentPropsWithRef<'header'>, keyof SiteHeaderOwnProps> {}

const isUnder = (href: string, currentHref?: string) =>
  currentHref != null && (currentHref === href || currentHref.startsWith(`${href}/`));

const sectionIsCurrent = (section: SiteHeaderSection, currentHref?: string) =>
  section.current ??
  (isUnder(section.href, currentHref) ||
    (section.mega?.items.some((item) => isUnder(item.href, currentHref)) ?? false));

/**
 * A site's top bar: the brand, a pill per section with a mega menu on any
 * section that has one, and actions at the end, sticking to the viewport
 * over a progressive blur whose tint arrives once the page scrolls. When
 * the pills no longer fit, measured on the bar's own width rather than the
 * viewport's, the bar folds to a menu button that opens a drawer of the
 * same sections. The forwarded ref and any unrecognised props target the
 * `<header>`.
 */
export function SiteHeader({
  brand,
  sections,
  currentHref,
  actions,
  wideActions,
  drawerFooter,
  drawerOpen: drawerOpenProp,
  defaultDrawerOpen = false,
  onDrawerOpenChange,
  initialFold = 'tablet',
  sticky = true,
  tintAfter = 48,
  linkComponent,
  navLabel = 'Primary',
  drawerOpenLabel = 'Open menu',
  drawerTitle = 'Menu',
  drawerCloseLabel = 'Close menu',
  className = '',
  ref,
  ...rest
}: SiteHeaderProps) {
  const Link = useLinkComponent(linkComponent);
  const baseClass = 'ds-site-header';
  const panelId = useId();

  const headerRef = useRef<HTMLElement | null>(null);
  const barRef = useRef<HTMLDivElement>(null);
  const brandRef = useRef<HTMLDivElement>(null);
  const navRef = useRef<HTMLElement>(null);
  const wideRef = useRef<HTMLDivElement>(null);
  const actionsRef = useRef<HTMLDivElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const menuButtonRef = useRef<HTMLButtonElement>(null);
  const closeTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  // Set while Escape hands focus back to a pill, so that focus does not
  // reopen the panel it just closed.
  const returningFocus = useRef(false);

  const [openId, setOpenId] = useState<string | null>(null);
  // The section whose content the panel holds. It outlives openId, so a
  // closing panel fades out with its rows still in it rather than empty.
  const [shownId, setShownId] = useState<string | null>(null);
  const [folded, setFolded] = useState(false);
  // False until the first measurement: the CSS fold stands in until then.
  const [measured, setMeasured] = useState(false);
  // The bar's place when the drawer opened, so the drawer's brand row lands
  // on the bar's own brand whatever the scroll, the gutter or the direction.
  const [drawerOffset, setDrawerOffset] = useState<React.CSSProperties>({});
  const [tinted, setTinted] = useState(false);
  const [drawerOpenState, setDrawerOpenState] = useState(defaultDrawerOpen);
  const drawerOpen = drawerOpenProp ?? drawerOpenState;
  const setDrawerOpen = useCallback(
    (next: boolean) => {
      if (drawerOpenProp === undefined) setDrawerOpenState(next);
      onDrawerOpenChange?.(next);
    },
    [drawerOpenProp, onDrawerOpenChange],
  );

  const setRef = (node: HTMLElement | null) => {
    headerRef.current = node;
    if (typeof ref === 'function') ref(node);
    else if (ref) ref.current = node;
  };

  // The fold: the room the full row needs against the room the bar has.
  // Folded pills stay in the DOM, hidden and out of flow, so they keep
  // their width for the next measurement; state changes only when the
  // answer flips, never per resize frame.
  useLayoutEffect(() => {
    const bar = barRef.current;
    if (!bar) return;
    const measure = () => {
      const style = getComputedStyle(bar);
      const gap = parseFloat(style.columnGap) || 0;
      const navStart = navRef.current ? parseFloat(getComputedStyle(navRef.current).marginInlineStart) || 0 : 0;
      const parts = [brandRef.current, navRef.current, wideRef.current, actionsRef.current];
      const widths = parts.map((el) => (el ? el.scrollWidth : 0));
      const present = widths.filter((w) => w > 0).length;
      const needed = widths.reduce((sum, w) => sum + w, 0) + navStart + gap * Math.max(present - 1, 0);
      setFolded(needed > bar.clientWidth);
      setMeasured(true);
    };
    measure();
    const observer = new ResizeObserver(measure);
    [bar, brandRef.current, navRef.current, wideRef.current, actionsRef.current].forEach(
      (el) => el && observer.observe(el),
    );
    return () => observer.disconnect();
  }, [sections, actions, wideActions, brand]);

  // The tint over the sticky blur follows the page's scroll past `tintAfter`.
  useEffect(() => {
    if (!sticky) return;
    let frame = 0;
    const check = () => {
      frame = 0;
      setTinted(window.scrollY > tintAfter);
    };
    const onScroll = () => {
      if (!frame) frame = requestAnimationFrame(check);
    };
    check();
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => {
      window.removeEventListener('scroll', onScroll);
      if (frame) cancelAnimationFrame(frame);
    };
  }, [sticky, tintAfter]);

  useEffect(() => () => clearTimeout(closeTimer.current), []);

  // As the drawer opens, measure where the bar and its menu button sit, so
  // the drawer's brand row lands on the bar's brand and its close button on
  // the menu button it replaces, whatever the scroll, the gutter or the
  // reading direction. Measured on open, not live: a scroll event mid-open
  // (iOS fires them as the scroll lock engages) must not move the X.
  useLayoutEffect(() => {
    if (!drawerOpen) return;
    const bar = barRef.current;
    if (!bar) return;
    const rtl = isRtl(bar);
    const start = (rect: DOMRect) => (rtl ? window.innerWidth - rect.right : rect.left);
    const barRect = bar.getBoundingClientRect();
    const offsets: Record<string, string> = {
      '--ds-site-header-height': `${bar.offsetHeight}px`,
      '--ds-site-header-drawer-top': `${Math.max(barRect.top, 0)}px`,
      '--ds-site-header-drawer-start': `${start(barRect)}px`,
    };
    const button = menuButtonRef.current?.getBoundingClientRect();
    if (button && button.width > 0) {
      offsets['--ds-site-header-close-top'] = `${button.top}px`;
      offsets['--ds-site-header-close-start'] = `${start(button)}px`;
    }
    setDrawerOffset(offsets as React.CSSProperties);
  }, [drawerOpen]);

  const openSection = useCallback((id: string) => {
    clearTimeout(closeTimer.current);
    setOpenId(id);
    setShownId(id);
  }, []);

  const scheduleClose = useCallback(() => {
    clearTimeout(closeTimer.current);
    closeTimer.current = setTimeout(() => setOpenId(null), MOTION_HOVER_HIDE_DELAY_MS);
  }, []);

  const closePanel = useCallback(() => {
    clearTimeout(closeTimer.current);
    setOpenId(null);
  }, []);

  const triggerFor = (id: string) =>
    navRef.current?.querySelector<HTMLElement>(`[data-section="${CSS.escape(id)}"]`) ?? null;

  // The open panel is a light-dismiss layer: an outside press or Escape
  // closes it through the shared stack, and Escape hands focus back to the
  // pill that opened it.
  useLayer({
    open: openId != null && !folded,
    onDismiss: () => {
      const trigger = openId ? triggerFor(openId) : null;
      const focusInPanel = panelRef.current?.contains(document.activeElement) ?? false;
      closePanel();
      if (focusInPanel && trigger) {
        returningFocus.current = true;
        trigger.focus();
        returningFocus.current = false;
      }
    },
    dismissOnOutsidePress: true,
    getElements: () => [navRef.current, panelRef.current],
  });

  // A fold closes any open panel; the drawer takes over.
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    if (folded) setOpenId(null);
    // Only a measured unfold closes the drawer: on mount `folded` is false
    // until the first measurement, and a drawer opened from the start
    // (`defaultDrawerOpen`, or a controlled `drawerOpen`) must survive that.
    else if (measured && drawerOpen) setDrawerOpen(false);
  }, [folded, measured, drawerOpen, setDrawerOpen]);

  const panelOpen = openId != null && sections.some((s) => s.id === openId && s.mega);
  const shown = sections.find((s) => s.id === shownId && s.mega) ?? null;

  const drawerItems: NavListItem[] = sections.map((section) => ({
    id: section.id,
    label: section.label,
    href: section.href,
    current: sectionIsCurrent(section, currentHref) || undefined,
    ...((section.drawerItems ?? section.mega?.items ?? []).length > 0
      ? { items: (section.drawerItems ?? section.mega?.items ?? []).map(({ href, label }) => ({ href, label })) }
      : {}),
  }));
  const currentSectionId = sections.find((s) => sectionIsCurrent(s, currentHref))?.id;

  const classes = [
    baseClass,
    sticky && `${baseClass}--sticky`,
    folded && `${baseClass}--folded`,
    !measured && initialFold !== 'never' && `${baseClass}--prefold-${initialFold}`,
    className,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <header {...rest} ref={setRef} className={classes}>
      {sticky && <ProgressiveBlur className={`${baseClass}__blur`} tinted={tinted} />}

      <div ref={barRef} className={`${baseClass}__bar`}>
        {brand && (
          <div ref={brandRef} className={`${baseClass}__brand`}>
            {brand}
          </div>
        )}

        <nav ref={navRef} aria-label={navLabel} className={`${baseClass}__nav`} inert={folded}>
          {sections.map((section) => {
            const current = sectionIsCurrent(section, currentHref);
            const open = openId === section.id;
            const pillClass = [
              `${baseClass}__pill`,
              open && `${baseClass}__pill--open`,
              current && `${baseClass}__pill--current`,
            ]
              .filter(Boolean)
              .join(' ');

            if (!section.mega) {
              return (
                <Link
                  key={section.id}
                  href={section.href}
                  data-section={section.id}
                  className={pillClass}
                  aria-current={current ? 'page' : undefined}
                  onMouseEnter={scheduleClose}
                  onClick={closePanel}
                >
                  {section.label}
                </Link>
              );
            }

            return (
              <div
                key={section.id}
                className={`${baseClass}__section`}
                onMouseEnter={() => openSection(section.id)}
                onMouseLeave={scheduleClose}
              >
                <Link
                  href={section.href}
                  data-section={section.id}
                  className={pillClass}
                  aria-current={current ? 'page' : undefined}
                  aria-expanded={open}
                  aria-controls={panelId}
                  onFocus={() => {
                    if (!returningFocus.current) openSection(section.id);
                  }}
                  onClick={closePanel}
                  onKeyDown={(event: React.KeyboardEvent<HTMLAnchorElement>) => {
                    // ArrowDown steps into the open panel, so its links are
                    // one key away rather than past every pill and action.
                    if (event.key !== 'ArrowDown') return;
                    event.preventDefault();
                    openSection(section.id);
                    requestAnimationFrame(() => panelRef.current?.querySelector<HTMLElement>('a')?.focus());
                  }}
                >
                  <span>{section.label}</span>
                  <span
                    className={`material-symbols-rounded ${baseClass}__caret`}
                    aria-hidden="true"
                  >
                    expand_more
                  </span>
                </Link>
              </div>
            );
          })}
        </nav>

        <div className={`${baseClass}__end`}>
          {actions && (
            <div ref={actionsRef} className={`${baseClass}__actions`}>
              {actions}
            </div>
          )}
          {wideActions && (
            <div ref={wideRef} className={`${baseClass}__wide-actions`} inert={folded}>
              {wideActions}
            </div>
          )}
          <CircularButton
            ref={menuButtonRef}
            className={[`${baseClass}__menu-button`, drawerOpen && `${baseClass}__menu-button--hidden`]
              .filter(Boolean)
              .join(' ')}
            icon="menu"
            variant="secondary"
            tone="neutral"
            ariaLabel={drawerOpenLabel}
            tooltip={false}
            aria-expanded={drawerOpen}
            aria-haspopup="dialog"
            onClick={() => setDrawerOpen(true)}
          />
        </div>

        <div
          className={`${baseClass}__panel`}
          onMouseEnter={() => openId && openSection(openId)}
          onMouseLeave={scheduleClose}
        >
          <MegaMenu
            ref={panelRef}
            id={panelId}
            open={panelOpen && !folded}
            items={shown?.mega?.items ?? []}
            showcase={shown?.mega?.showcase}
            currentHref={currentHref}
            linkComponent={Link}
            onNavigate={closePanel}
          />
        </div>
      </div>

      <Drawer
        open={drawerOpen}
        onOpenChange={setDrawerOpen}
        title={drawerTitle}
        closeLabel={drawerCloseLabel}
        side="start"
        size="sm"
        footer={drawerFooter}
        className={`${baseClass}__drawer`}
        style={drawerOffset}
        heading={
          brand && (
            <div
              className={`${baseClass}__drawer-brand`}
              onClick={(event) => {
                // The brand usually links home: following it closes the drawer.
                if ((event.target as HTMLElement).closest('a')) setDrawerOpen(false);
              }}
            >
              {brand}
            </div>
          )
        }
      >
        <NavList
          key={drawerOpen ? 'open' : 'closed'}
          items={drawerItems}
          currentHref={currentHref}
          defaultExpandedIds={currentSectionId ? [currentSectionId] : []}
          linkComponent={Link}
          onNavigate={() => setDrawerOpen(false)}
        />
      </Drawer>
    </header>
  );
}
